import{_ as n,C as o,c as s,o as r,a3 as a,G as c}from"./chunks/framework.Dokpd4od.js";const m=JSON.parse('{"title":"Default accounts","description":"","frontmatter":{},"headers":[],"relativePath":"master/finance/get-started/default-accounts.md","filePath":"master/finance/get-started/default-accounts.md","lastUpdated":1792041590000}'),i={name:"master/finance/get-started/default-accounts.md"};function l(u,e,h,p,d,g){const t=o("ImagePopup");return r(),s("div",null,[e[0]||(e[0]=a('<h1 id="default-accounts" tabindex="-1">Default accounts <a class="header-anchor" href="#default-accounts" aria-label="Permalink to &quot;Default accounts&quot;">​</a></h1><p>Some accounts are needed in many places: where to book a currency gain, where to park money in transit, which account a new product sells into. The Manage Default Accounts page lets you choose these once. Aureus then fills them in for you.</p><blockquote><p><strong>In simple words:</strong> Pick the standard account for each situation. You will not have to pick it again each time.</p></blockquote><h2 id="open-the-page" tabindex="-1">Open the page <a class="header-anchor" href="#open-the-page" aria-label="Permalink to &quot;Open the page&quot;">​</a></h2><p>Go to <code>Accounting → Settings → Manage Default Accounts</code>. This page exists only in the <strong>Accounting</strong> app. If it shows only a warning box, run <a href="./accounting-setup.html">Set up accounting</a> first.</p>',5)),c(t,{src:"/images1/finance/settings_default_accounts.png",alt:"Accounting → Settings → Manage Default Accounts with the three sections filled in"}),e[1]||(e[1]=a('<h2 id="update-the-defaults" tabindex="-1">Update the defaults <a class="header-anchor" href="#update-the-defaults" aria-label="Permalink to &quot;Update the defaults&quot;">​</a></h2><ol><li>Open <code>Accounting → Settings → Manage Default Accounts</code>.</li><li>Choose an account or journal in each field.</li><li>Click <strong>Save changes</strong>.</li></ol><p>Only accounts that are not deprecated are listed.</p><h2 id="exchange-difference-entries" tabindex="-1">Exchange Difference Entries <a class="header-anchor" href="#exchange-difference-entries" aria-label="Permalink to &quot;Exchange Difference Entries&quot;">​</a></h2><p>Used when you receive or pay in a foreign currency and the exchange rate has moved. See <a href="./multi-currency.html">Foreign currencies</a>.</p><ul><li><strong><em>Journal:</em></strong> The journal that holds the exchange difference entries. The sample company uses <strong>Exchange Difference</strong>.</li><li><strong><em>Gain:</em></strong> An <strong>Income</strong> or <strong>Other Income</strong> account for gains. Sample: <strong>Foreign Exchange Gain</strong>.</li><li><strong><em>Loss:</em></strong> An expense account (<strong>Expenses</strong>, <strong>Depreciation</strong> or <strong>Cost of Revenue</strong>) for losses. Sample: <strong>Foreign Exchange Loss</strong>.</li></ul><p>When a payment is matched to an invoice and a difference is left, Aureus posts an entry in this journal. If the journal or the accounts are empty, the match fails with an error. Fill them in before you work in foreign currencies.</p><h2 id="bank-transfer-and-payments" tabindex="-1">Bank Transfer and Payments <a class="header-anchor" href="#bank-transfer-and-payments" aria-label="Permalink to &quot;Bank Transfer and Payments&quot;">​</a></h2><ul><li><strong><em>Bank Suspense Account:</em></strong> A current asset or current liability account. Aureus uses it as the suspense account of a bank, cash or credit card journal that has none of its own. Sample: <strong>Bank Suspense Account</strong>.</li><li><strong><em>Transfer Account:</em></strong> A current asset account that allows reconcile. It holds money moving between your own bank and cash journals. Sample: <strong>Liquidity Transfer</strong>.</li></ul><h2 id="product-accounts" tabindex="-1">Product Accounts <a class="header-anchor" href="#product-accounts" aria-label="Permalink to &quot;Product Accounts&quot;">​</a></h2><ul><li><strong><em>Income Account:</em></strong> The account new products sell into. Sample: <strong>Product Sales</strong>.</li><li><strong><em>Expense Account:</em></strong> The account new products are bought into. Sample: <strong>Expenses</strong>.</li></ul><p>These two accounts appear as the starting value in the account fields of a new product and a new product category. You can still change them per product or per category. See <a href="./../../sales/sales/products-prices/manage-products.html">Manage products</a>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Receivable, payable, bank and cash types, credit card and off balance accounts are not offered as product accounts.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Settings are kept per company. If you work with several companies, check the page in each one.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./chart-of-accounts.html">Chart of accounts</a></li><li><a href="./journals.html">Journals</a></li><li><a href="./multi-currency.html">Foreign currencies</a></li><li><a href="./accounting-setup.html">Set up accounting</a></li></ul>',16))])}const _=n(i,[["render",l]]);export{m as __pageData,_ as default};
